class Stack:
    def __init__(self):
        self._items = []

    def push(self, item):
        self._items.append(item)

    def pop(self):
        if self.is_empty():
            raise IndexError('Stack is empty')
        return self._items.pop()

    def peek(self):
        if self.is_empty():
            raise IndexError('Stack is empty')
        return self._items[-1]

    def is_empty(self) -> bool:
        return len(self._items) == 0

    def size(self) -> int:
        return len(self._items)


s = Stack()
s.push(1)
s.push(2)
print(s.peek())  # 2
print(s.pop())   # 2
print(s.size())  # 1
```

